    function topList(items, comparison = false) {
      return `<ol class="dl-top-list">${items.slice(0, 5).map((a) => {
        const delta = preview.rows.find((r) => r.id === a.id);
        return `<li><span class="dl-position">${a.rank}</span><div><strong>${T(a.shortName)}</strong><small>${T(a.track?.title)}</small>${comparison ? `<span class="dl-delta">${L3("\u0418\u043D\u0434\u0435\u043A\u0441", "Index")} ${D(delta.scoreDelta)} \xB7 ${delta.rankDelta === 0 ? L3("\u043C\u0435\u0441\u0442\u043E \u043F\u0440\u0435\u0436\u043D\u0435\u0435", "same rank") : delta.rankDelta > 0 ? L3("\u0432\u044B\u0448\u0435 \u043D\u0430 ", "up ") + delta.rankDelta : L3("\u043D\u0438\u0436\u0435 \u043D\u0430 ", "down ") + Math.abs(delta.rankDelta)}</span>` : ""}</div><b>${F2(a.score)}</b></li>`;
      }).join("")}</ol>`;
    }
